INK='#202522'; PAPER='#F6F3EC'; LILAC='#D8CEF2'; SAGE='#DDE7DC'; CORAL='#B8422B';COL={'Allow':'#226043','Requires counsel':'#79500C','Deny':'#942F32'}
def text(x,y,t,size=16,color=INK,weight=400):return f'<text x="{x}" y="{y}" fill="{color}" font-size="{size}" font-weight="{weight}">{html.escape(str(t))}</text>'
def rect(x,y,w,h,fill,rx=10):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}"/>'
def line(x,y,X,Y,color='#8B948D',dash=False):return f'<path d="M{x},{y} L{X},{Y}" fill="none" stroke="{color}" stroke-width="1.5"'+(' stroke-dasharray="5 5"' if dash else '')+'/>'
def node(x,y,w,title,sub,fill=LILAC):return rect(x,y,w,76,fill)+text(x+18,y+30,title,19,weight=600)+text(x+18,y+55,sub,13)
def arrow(x,y,X,Y,label=''):
 return line(x,y,X,Y,CORAL)+f'<path d="M{X-7},{Y-5} L{X},{Y} L{X-7},{Y+5}" fill="none" stroke="{CORAL}" stroke-width="1.5"/>'+text((x+X)/2-25,y-12,label,12)
assets=[]
def save(slug,title,body,desc,cat='Diagrams',bg=PAPER):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 480" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(desc)}</desc><rect width="800" height="480" fill="{bg}"/><g font-family="Arial,sans-serif">'+text(32,36,'CONSENT WAYPOINT / CONCEPT PREVIEW',11)+text(32,82,title,28,weight=600)+body+text(32,453,'DEMO — SYNTHETIC DATA · NO EXECUTIONS',11)+'</g></svg>'
 (d/f'{slug}.svg').write_text(s);assets.append((slug,title,desc,cat))
