b+=text(215,415,'0',12)+text(657,415,'4 evaluations',12)
save('outcome-bars','Three outcomes. Twelve evaluations.',b,'Allow: 4. Requires counsel: 4. Deny: 4. Counts of synthetic evaluations, not executed requests.','Charts')
