b+=line(64,350,760,350)+text(32,145,'Evaluations per day · zero baseline · 12 total',14)
save('daily-evaluations','A small, inspectable sample.',b,'01 Oct:1; 02 Oct:1; 03 Oct:2; 04 Oct:2; 05 Oct:1; 06 Oct:2; 07 Oct:1; 08 Oct:2. Synthetic event counts.','Charts')
