# Table helpers

def table(headers,rs,caption):
 return '<div class="table-wrap" tabindex="0" role="region" aria-label="'+caption+'"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in r)+'</tr>' for r in rs)+'</tbody></table></div>'
cards=''
for i,(slug,title,desc,cat) in enumerate(assets):
 cards+=f'<article class="asset" data-kind="{cat}"><div class="asset-top"><span>{cat} / {i+1:02}</span><a href="library/{slug}.svg" download aria-label="Download {title}">SVG ↓</a></div><div class="figure-window"><img src="library/{slug}.svg" alt="{html.escape(desc)}" width="800" height="480" loading="lazy"></div><div class="asset-copy"><h3>{title}</h3><p>{desc}</p></div></article>'
